const assert=require('node:assert/strict');
const G=require('./dist/engine.js'),{CARDS,CARD}=require('./dist/data.js');let passed=0;
function test(n,f){try{f();passed++;console.log('PASS '+n)}catch(e){console.error('FAIL '+n+' — '+e.message);process.exitCode=1}}
function fixture(list,leader='none'){let r=G.newRun(leader,{},71);r.roster=list.map(([id])=>G.instance(r,id));r.phase='ready';r.depth=5;r.node={type:'battle',row:5};let original=JSON.parse(JSON.stringify(r.roster));let b=G.deploy(r);r.roster=original;r.roster.forEach(u=>{u.permanentAtkBonus=0;u.threshold=0});r.stats.growth=0;b.units=r.roster.map((u,i)=>G.runtime(b,u,list[i][1]));b.units.forEach(u=>G.prepareHooks(b,u));b.effects=[];b.openingResolved=false;b.events=[];b.feedback=[];b.run.devoured=[];b.metrics={kills:0,leaks:0,growth:0,triggers:0,devours:0};b.plan={count:0,interval:1,hp:100,speed:.3};b.spawned=0;return b}
function enemy(b,p=3,hp=10000,extra={}){let e={uid:++b.enemyUid,p,hp,maxHp:hp,speed:.3,leak:2,defense:0,gone:false,slows:[],frozenUntil:0,shredUntil:0,bleeds:[],auras:[],...extra};b.enemies.push(e);return e}
function u(b,id){return b.units.find(u=>u.id===id)}
function advance(b,t){for(let i=0;i<Math.ceil(t*30)&&!b.done;i++)G.step(b,1/30)}
test('coin rerolls repeat, cost 10, and leave health unchanged',()=>{let r=G.newRun('shen',{},19);assert(!G.rerollDraft(r));r.coins=30;let hp=r.health;assert(G.rerollDraft(r));assert.equal(r.coins,20);assert(G.rerollDraft(r));assert.equal(r.coins,10);assert(G.rerollDraft(r));assert.equal(r.coins,0);assert.equal(r.health,hp);let snap=JSON.stringify(r);assert(!G.rerollDraft(r));assert.equal(JSON.stringify(r),snap);});

test('battle payouts give normal 100, elite 200 and boss 500 on wins and losses',()=>{for(const [type,coins,won] of [['battle',100,true],['elite',200,false],['boss',500,false]]){let b=fixture([['jade',4]]);b.run.node={type};b.run.coins=9;G.finish(b,won);assert.equal(b.run.coins,9+coins);assert.equal(b.run.recap.coinsEarned,coins)}});
test('leader draft bias favors its genre while preserving rarity tiers',()=>{let favored=0,unfavored=0;for(let seed=1;seed<=1000;seed++){favored+=G.newRun('shen',{},seed).offers.filter(id=>CARD[id].genre==='Cultivation').length;unfavored+=G.newRun('yara',{},seed).offers.filter(id=>CARD[id].genre==='Cultivation').length}assert(favored>unfavored+25,`${favored} vs ${unfavored}`);let r=G.newRun('shen',{},14);r.depth=8;r.node={type:'battle'};assert.deepEqual(G.rewardWeights(r),[50,32,15,3,0])});
test('Lotus refinement continues beyond the former per-battle cap',()=>{let b=fixture([['lotus',0],['cannon',8]]);for(let i=0;i<8;i++)G.refine(b,b.units[0]);assert.equal(b.units[1].permanentAtkBonus,48);assert.equal(b.units[0].refinements,8);});
test('Immortal keeps full leading damage but secondary hits are 55 percent',()=>{let b=fixture([['immortal',4]]);b.run.leader='none';let a=enemy(b,7),z=enemy(b,6),y=enemy(b,5);b.run.seed=12345;G.attack(b,b.units[0]);let hits=[a,z,y].map(e=>10000-e.hp);assert(hits[1]===11||hits[1]===22);assert(hits[2]===11||hits[2]===22);assert(hits[0]===20||hits[0]===40);});
test('early growth engines are draftable before Epic unlocks',()=>{for(const id of ['jade','heir','mantis','nanite','smelter','altar','lotus','cauldron'])assert(G.tier(id)<=1,id);let seen=new Set();for(let seed=1;seed<500;seed++){const r=G.newRun('shen',{},seed);r.depth=1;r.node={type:'battle'};G.offers(r).forEach(id=>seen.add(id));}assert(seen.has('cub'));assert(seen.has('cauldron'));});
test('late finishers have no hidden self growth after attacks, triggers, or kills',()=>{for(const id of ['railgun','executioner','eye','mage','weaver','behemoth','core','reaper']){let b=fixture([[id,4]]),v=b.units[0];enemy(b,2,1e8,{speed:0});for(let i=0;i<20;i++){G.attack(b,v);if(v.threshold.max){v.state='active';b.time+=10;G.tick(b,v,v.threshold.max);}G.damage(b,enemy(b,1,1),2,v);}assert.equal(v.permanentAtkBonus,0,id);}});
test('Team Power excludes reserves, consumed originals, and tokens',()=>{let b=fixture([['mage',4],['jade',1],['hound',8]]);G.growth(b,b.units[0],10);G.growth(b,b.units[1],40);const t=G.spawnToken(b,b.units[2],'houndToken',true,{origin:'hound',tokenAtk:16});G.growth(b,t,999);const reserve=G.instance(b.run,'jade');reserve.permanentAtkBonus=1000;b.run.roster.push(reserve);assert.equal(G.teamPower(b),50);b.units[1].removed=true;assert.equal(G.teamPower(b),10);});
test('Railgun immediately converts established allied growth into volley damage',()=>{let a=fixture([['railgun',0],['jade',8]]),b=fixture([['railgun',0],['jade',8]]);G.growth(b,b.units[1],100);let x=enemy(a),y=enemy(b);a.run.seed=b.run.seed=12345;G.attack(a,a.units[0]);G.attack(b,b.units[0]);assert(y.hp<x.hp);assert.equal(b.units[0].permanentAtkBonus,0);});
test('late spell and collapse payoffs scale with existing team growth',()=>{for(const id of ['mage','weaver','behemoth','core']){let a=fixture([[id,0],['jade',8]]),b=fixture([[id,0],['jade',8]]);G.growth(b,b.units[1],100);let x=enemy(a),y=enemy(b);a.run.seed=b.run.seed=12345;G.tick(a,a.units[0],a.units[0].threshold.max);G.tick(b,b.units[0],b.units[0].threshold.max);assert(y.hp<x.hp,id);assert.equal(b.units[0].permanentAtkBonus,0,id);}});
test('Burn and Bleed retain 150 independent stacks and expire separately',()=>{for(const type of ['burn','bleed']){let b=fixture([['bellows',0]]),e=enemy(b,2,1e8,{speed:0}),key=type==='burn'?'burns':'bleeds';b.units[0].attackInterval=0;for(let i=0;i<100;i++)G.dot(b,e,type,1,4,b.units[0]);b.time=2;for(let i=0;i<50;i++)G.dot(b,e,type,1,4,b.units[0]);assert.equal(e[key].length,150);b.time=4.01;G.step(b,.01);assert.equal(e[key].length,50);b.time=6.01;G.step(b,.01);assert.equal(e[key].length,0);}});
test('cooldown gauges retain overflow instead of silently discarding charge',()=>{let b=fixture([['eye',0]]),v=b.units[0];v.nextTrigger=10;G.tick(b,v,120);assert.equal(v.threshold.current,120);b.time=10;G.tick(b,v,0);assert.equal(v.threshold.current,108);assert.equal(v.nextTrigger,14);});
test('Arcane leader cannot charge removed Heir attack growth',()=>{let b=fixture([['cannon',0],['heir',4]],'lyra');G.tick(b,b.units[0],4);G.tick(b,b.units[1],100);assert.equal(b.units[0].threshold.current,4);assert.equal(b.units[1].permanentAtkBonus,0);assert.equal(b.units[1].threshold.max,0);});
test('Nanites gain unlimited permanent attack from critical hits',()=>{let b=fixture([['nanite',4]]),v=b.units[0],e=enemy(b,1,1e8);v.critGift=true;for(let i=0;i<120;i++)G.hit(b,v,e,1);assert.equal(v.permanentAtkBonus,20);assert.equal(e.nanoUntil,3);});
test('Cauldron cooldown prevents repeated same-moment rewards but never caps total brews',()=>{let b=fixture([['cauldron',0],['jade',8]]);for(let i=0;i<30;i++){b.time=i*8;G.event(b,'breakthrough',{unit:b.units[1]});G.event(b,'breakthrough',{unit:b.units[1]});G.flushEvents(b);}assert.equal(b.units[0].elixirs,30);assert.equal(b.units[1].permanentAtkBonus,30);});
test('Reaper payoff depends on all remaining Bleed damage, not a flat capped bonus',()=>{let a=fixture([['reaper',0]]),b=fixture([['reaper',0]]),x=enemy(a),y=enemy(b);for(let i=0;i<4;i++)G.dot(a,x,'bleed',2,4,a.units[0]);for(let i=0;i<40;i++)G.dot(b,y,'bleed',2,4,b.units[0]);a.run.seed=b.run.seed=12345;G.attack(a,a.units[0]);G.attack(b,b.units[0]);assert(y.hp<x.hp);assert.equal(x.bleeds.length,1);assert.equal(y.bleeds.length,1);});
test('Mind Larva doubles its fifth hit, not the following attack',()=>{let b=fixture([['larva',0]]),v=b.units[0],e=enemy(b);v.attackCount=4;b.run.seed=12345;G.attack(b,v);assert([22,44,28,56].includes(10000-e.hp));});
test('duplicate aura winner uses numeric instance order even past UID nine',()=>{let b=fixture([['smelter',0],['smelter',8]]);b.units[0].uid=2;b.units[1].uid=10;assert.equal(G.support(b,'smelter').uid,2);});
test('unlimited growth survives JSON roundtrip and evolved deployment',()=>{let b=fixture([['jade',4]]);for(let i=0;i<60;i++)G.tick(b,b.units[0],36);assert.equal(b.units[0].permanentAtkBonus,180);G.finish(b,true);const r=JSON.parse(JSON.stringify(b.run));r.phase='ready';let z=G.deploy(r);assert.equal(z.units[0].id,'immortal');assert.equal(z.units[0].permanentAtkBonus,180);});
test('card rules are present, consolidated, and do not advertise removed growth limits',()=>{for(const c of [...CARDS,...require('./dist/data.js').FORMS,...require('./dist/data.js').TOKENS]){assert(c.rules?.trim(),c.id);assert(c.synergy?.trim(),c.id);assert(!/undefined|NaN/.test(c.rules),c.id);assert(!/cap \+|capped at|stack cap|Maximum 3 refinements|Maximum 3 elixirs/.test(c.rules),c.id);assert(!('spatial' in c),c.id);}});
test('Spirit grows on every completed return and retains growth after evolving',()=>{let b=fixture([['spirit',4]]),v=b.units[0];for(let i=0;i<20;i++){G.flip(b,v,'dormant',5);G.flip(b,v,'active');}assert.equal(v.id,'wraith');assert.equal(v.permanentAtkBonus,20);assert.equal(b.run.roster[0].permanentAtkBonus,20);});
test('Wraith has an immediate boss-damage payoff after evolution',()=>{let a=fixture([['wraith',0]]),b=fixture([['wraith',0]]),x=enemy(a),y=enemy(b,3,10000,{boss:true});a.run.seed=b.run.seed=12345;G.attack(a,a.units[0]);G.attack(b,b.units[0]);assert.equal(10000-y.hp,(10000-x.hp)*1.5);});
test('Railgun field ATK includes its live allied-growth bonus',()=>{let b=fixture([['railgun',0],['jade',8]]);G.growth(b,b.units[1],100);assert.equal(G.atk(b,b.units[0]),235);b.units[1].removed=true;assert.equal(G.atk(b,b.units[0]),35);});
test('Blood Cub and attacking fodder are included in the Bloodline ecosystem',()=>{assert(CARDS.some(c=>c.id==='cub'));assert(['serpentFodder','scuttler','flameToad','peachFodder'].every(id=>CARD[id]?.baseAtk>0));assert.equal(require('./dist/data.js').FORMS.filter(c=>c.lineage).length,20);});
test('one starting attacker chosen from three unique offers; full route pre-generated',()=>{for(let seed=0;seed<50;seed++){let r=G.newRun('shen',{},seed);assert.equal(r.offers.length,3);assert.equal(new Set(r.offers).size,3);assert(r.offers.every(id=>CARD[id].baseAtk>0));assert.equal(r.map.length,16);assert.equal(r.map.flat().length,46);assert(G.draft(r,r.offers[0]));assert.equal(r.roster.length,1);assert.equal(r.phase,'map');assert.equal(G.available(r).length,3)}});
test('map enforces connections and rewards require a fresh draft',()=>{let r=G.newRun('shen',{},1);G.draft(r,r.offers[0]);assert(!G.chooseNode(r,'2-1'));assert(G.chooseNode(r,'0-0'));G.reward(r);assert.equal(G.available(r).length,0);G.draft(r,r.offers[0]);assert.deepEqual(G.available(r).map(n=>n.id),['1-0','1-1']);assert(!G.chooseNode(r,'1-2'))});
test('random deployment capped at nine unique slots; no cost or manual arrangement',()=>{let r=G.newRun('shen',{},22);r.roster=Array.from({length:20},()=>G.instance(r,'jade'));r.phase='ready';r.depth=0;r.node={type:'battle'};let b=G.deploy(r);assert.equal(b.units.length,9);assert.equal(new Set(b.units.map(u=>u.slot)).size,9);assert.equal(new Set(b.units.map(u=>u.uid)).size,9);assert.equal(r.phase,'combat');assert(!('res' in r));assert(!('energy' in r));});
test('sixteen unique clockwise track tiles surround the nine interior cells',()=>{assert.equal(G.ring.length,16);assert.equal(new Set(G.ring.map(p=>p.join(','))).size,16);assert.deepEqual(G.track(0),{x:0,y:0});assert.deepEqual(G.track(4),{x:4,y:0});assert.deepEqual(G.track(8),{x:4,y:4});assert.deepEqual(G.track(12),{x:0,y:4});assert.equal(G.kind(4),'center');assert.equal([0,2,6,8].every(i=>G.kind(i)==='corner'),true)});
test('all normal attacks target the leading runner regardless of range',()=>{let b=fixture([['jade',0]]),near=enemy(b,1),far=enemy(b,10);G.attack(b,u(b,'jade'));assert.equal(near.hp,10000);assert(far.hp<10000)});
test('Cub first meal locks lineage and grants permanent ATK plus evolution stack',()=>{let b=fixture([['cub',4],['serpentFodder',1],['hound',3]]);assert(G.devour(b,b.units[0]));assert.equal(b.units[0].lineage,'dragon');assert.equal(b.units[0].permanentAtkBonus,4);assert.equal(b.units[0].lineageStacks,1);assert(b.units[1].removed);assert(!b.units[2].removed);});
test('Hound seeks wounded enemies and doubles its damage',()=>{let b=fixture([['hound',4]]),lead=enemy(b,10),weak=enemy(b,3,100,{hp:29});G.attack(b,u(b,'hound'));assert.equal(lead.hp,10000);assert.equal(weak.hp,0)});
test('Heir rejects cosmic prey while Herald consumes it',()=>{let b=fixture([['heir',4],['mass',1]]);assert(!G.devour(b,b.units[0]));b=fixture([['herald',4],['mass',1]]);assert(G.devour(b,b.units[0]));assert.equal(b.units[0].permanentAtkBonus,10);});
test('leaks remove enemies and damage only player; zero health ends run',()=>{let b=fixture([['herb',4]]);b.run.health=3;enemy(b,15.999,10,{leak:3});G.step(b,.1);assert.equal(b.run.health,0);assert.equal(b.run.phase,'lost');assert.equal(b.enemies.length,0);assert(b.done);assert(!('hp' in b.units[0]))});
test('pre-deployment JSON checkpoint reproduces the same formation and outcome',()=>{let r=G.newRun('shen',{},123);G.draft(r,r.offers[0]);G.chooseNode(r,'0-1');let clone=JSON.parse(JSON.stringify(r)),a=G.deploy(r),b=G.deploy(clone);advance(a,120);advance(b,120);assert.equal(a.done,true);assert.deepEqual(r,clone);assert.deepEqual(a.metrics,b.metrics)});
test('burn and vulnerable tick dynamically without triggering crowd-control gauges',()=>{let b=fixture([['eye',4],['jade',1]]),e=enemy(b,3,1000);G.status(b,e,'burn',2,10);G.status(b,e,'vulnerable',3,.5);assert.equal(u(b,'eye').threshold.current,0);let before=e.hp;G.hit(b,u(b,'jade'),e,100);assert(before-e.hp>=150);b.units.forEach(v=>v.attackInterval=0);let after=e.hp;advance(b,.5);assert(e.hp<after-4);assert.equal(e.frozenUntil,0)});
test('skip refuses the first draft and preserves roster and health on rewards',()=>{let r=G.newRun('shen',{},4);assert(!G.skipDraft(r));G.draft(r,r.offers[0]);G.reward(r);let before=JSON.stringify(r.roster),hp=r.health;assert(G.skipDraft(r));assert.equal(JSON.stringify(r.roster),before);assert.equal(r.health,hp);assert.equal(r.phase,'map');assert(!G.skipDraft(r))});
test('coin rerolls replace choices repeatedly without spending health',()=>{let r=G.newRun('shen',{},4);r.coins=20;let old=[...r.offers],hp=r.health;assert(G.rerollDraft(r));assert.equal(r.coins,10);assert(r.offers.every(id=>!old.includes(id)&&CARD[id].baseAtk>0));let prev=[...r.offers];assert(G.rerollDraft(r));assert.equal(r.coins,0);assert(r.offers.every(id=>!prev.includes(id)));assert.equal(r.health,hp);});
test('permanent devour removes upgraded instances without affecting duplicates',()=>{let b=fixture([['heir',4],['hound',1],['hound',8]]);let victim=u(b,'hound').uid;G.devour(b,b.units[0]);assert(!b.run.roster.some(v=>v.uid===victim));assert.equal(b.run.roster.filter(v=>v.id==='hound').length,1);assert.equal(b.run.devoured.at(-1).uid,victim);G.finish(b,true);assert.equal(b.run.phase,'draft')});
test('boss resists control and enrage prevents permanent stun or knockback',()=>{let b=fixture([['eye',4]]),e=enemy(b,12,100000,{boss:true,bornAt:-46,enraged:false});G.status(b,e,'slow',4,.4);assert.equal(e.slows[0].power,.2);G.status(b,e,'freeze',2);assert.equal(e.frozenUntil,1);G.tick(b,u(b,'eye'),12);assert.equal(e.p,10);G.step(b,.05);assert(e.enraged);assert.equal(e.frozenUntil,0);let p=e.p;G.tick(b,u(b,'eye'),12);assert.equal(e.p,p);G.status(b,e,'stun',10);assert.equal(e.frozenUntil,0)});
test('damage report caps overkill and attributes kills to the attacking instance',()=>{let b=fixture([['jade',4]]),e=enemy(b,3,20);G.damage(b,e,100,b.units[0]);let r=G.report(b);assert.equal(r.damage,20);assert.equal(r.cards[0].direct,20);assert.equal(r.cards[0].kills,1)});
test('Bleed remains credited to its attacker, not the enabling Totem',()=>{let b=fixture([['totem',4],['cannon',1]]),e=enemy(b,3,10000);G.attack(b,u(b,'cannon'));b.units.forEach(v=>v.attackInterval=0);advance(b,.5);let rows=G.report(b).cards;assert(rows.find(v=>v.id==='cannon').dot>.8);assert.equal(rows.find(v=>v.id==='totem').damage,0)});
test('feedback throttles visuals while preserving every interaction count',()=>{let b=fixture([['jade',4],['cannon',1]]);b.feedback=[];b.metrics.interactions={};for(let i=0;i<10;i++)G.interact(b,b.units[1],b.units[0],'test','test');assert.equal(b.feedback.length,1);assert.equal(G.report(b).interactions[0].count,10)});
test('devour report preserves consumed identity, destination, and gain across JSON',()=>{let b=fixture([['heir',4],['hound',1],['hound',8]]);G.devour(b,b.units[0]);G.finish(b,false);let recap=JSON.parse(JSON.stringify(b.run.recap));assert.equal(recap.consumed.length,1);assert.equal(recap.consumed[0].id,'hound');assert.equal(recap.consumed[0].bonus,3);assert.equal(recap.cards.filter(v=>v.id==='hound'&&v.consumed).length,1);assert(recap.notes.some(v=>v.includes('permanently lost')))});
test('early route exposes all three distinct threat profiles with matching spawns',()=>{assert.equal(new Set([0,1,2].map(lane=>G.encounterFor({type:'battle',row:1,lane}).id)).size,3);for(let lane=0;lane<3;lane++){let b=fixture([['jade',4]]);b.run.depth=1;b.run.node={type:'battle',row:1,lane};b.plan=G.wavePlan(b.run);for(let i=0;i<3;i++)G.spawn(b);if(b.plan.encounter==='armor')assert.equal(b.enemies.filter(e=>e.armored).length,2);if(b.plan.encounter==='fast')assert.equal(b.enemies.filter(e=>e.swift).length,2);if(b.plan.encounter==='packs')assert.equal(b.plan.count,18)}});
test('zero-trigger cards receive actionable recap feedback',()=>{let b=fixture([['jade',0]]);assert(G.report(b).notes.some(v=>v.includes('did not fill a trigger gauge')))});
test('Harbingers appear on all routes at crossings 6, 10, 14 only',()=>{for(let row=0;row<16;row++)for(let lane=0;lane<3;lane++){assert.equal(!!G.trialFor({row,lane,type:'battle'}),[5,9,13].includes(row))}assert.equal(G.trialFor({row:5,type:'rest'}),null)});
test('Harbinger replaces the final runner and has previewed HP and leak damage',()=>{let b=fixture([['herb',4]]);b.run.node={row:5,type:'battle',lane:1};b.run.depth=5;b.plan=G.wavePlan(b.run);b.spawned=b.plan.count-1;G.spawn(b);let e=b.enemies[0];assert(e.champion&&!e.boss&&!e.armored&&!e.swift);assert.equal(e.hp,1800);assert.equal(e.leak,10);assert.equal(e.defense,.2)});
test('Harbinger leak is survivable and its remaining HP persists in battle history',()=>{let b=fixture([['herb',4]]);b.run.health=100;enemy(b,15.999,1800,{champion:true,leak:10,bornAt:0});G.step(b,.1);assert.equal(b.run.health,90);assert.equal(b.run.phase,'draft');let h=JSON.parse(JSON.stringify(b.run.battleHistory));assert.equal(h[0].trial.killed,false);assert.equal(h[0].trial.hpRemaining,1800);assert(b.run.recap.notes.length>0)});
test('Harbinger resistance and enrage teach boss control limits',()=>{let b=fixture([['herb',4]]),e=enemy(b,5,1800,{champion:true,bornAt:-46,enraged:false});G.status(b,e,'slow',4,.4);assert.equal(e.slows[0].power,.2);G.status(b,e,'freeze',2);assert.equal(e.frozenUntil,1);G.step(b,.05);assert(e.enraged);assert.equal(e.frozenUntil,0);G.status(b,e,'freeze',3);assert.equal(e.frozenUntil,0)});
test('late-track kills record narrow safety margins and completed trial evidence',()=>{let b=fixture([['jade',4]]),e=enemy(b,13,20,{champion:true,bornAt:0,maxProgress:14});G.damage(b,e,30,b.units[0]);G.finish(b,true);assert.equal(b.run.recap.closeCalls,1);assert.equal(b.run.battleHistory[0].trial.killed,true);assert.equal(b.run.battleHistory[0].trial.progress,14)});
test('intro stays unchanged and final boss has 11000 HP with a fatal leak',()=>{let r=G.newRun('shen',{},1);r.depth=0;r.node={row:0,type:'battle'};assert.equal(G.wavePlan(r).hp,9);r.depth=15;r.node={row:15,type:'boss'};assert.equal(G.wavePlan(r).bossHp,11000);let b=fixture([['herb',4]]);b.run.relics=['mercy'];enemy(b,15.999,11000,{boss:true,leak:100,bornAt:0});G.step(b,.1);assert.equal(b.run.phase,'lost')});

test('Jade receives attacks across the team in every slot and has slower growth',()=>{for(const slot of [0,1,4,8]){let b=fixture([['jade',slot],['cannon',slot===8?0:8]]);enemy(b);for(let i=0;i<36;i++)G.attack(b,u(b,'cannon'));assert.equal(u(b,'jade').permanentAtkBonus,3);assert.equal(u(b,'jade').threshold.current,0)}});
test('Herb charges team gauges at opening and every twelve seconds',()=>{let b=fixture([['herb',0],['mage',8],['jade',6]]);G.startAbilities(b);assert.equal(u(b,'mage').threshold.current,3);enemy(b,2,100000);b.units.forEach(v=>v.attackInterval=0);advance(b,12.1);assert.equal(u(b,'mage').threshold.current,6);assert.equal(u(b,'jade').threshold.current,6)});
test('distant dormant Spirit buffs team without duplicate stacking',()=>{let b=fixture([['jade',0],['spirit',8],['spirit',6]]);b.units.filter(v=>v.id==='spirit').forEach(v=>v.state='dormant');assert.equal(G.atk(b,u(b,'jade')),16.8)});
test('distant state change empowers Bell equally in every slot',()=>{for(let slot of [0,4,8]){let b=fixture([['bell',slot],['spirit',slot===8?0:8]]),e=enemy(b);G.flip(b,u(b,'spirit'),'dormant',5);G.attack(b,u(b,'bell'));assert(e.hp<10000-30);assert.equal(e.frozenUntil,.75)}});
test('Heir has no positional speed bonus and skips nonadjacent Fodder',()=>{let b=fixture([['heir',0],['herb',1]]);G.startAbilities(b);assert.equal(G.speed(b,u(b,'heir')),1);b=fixture([['heir',4],['herb',0]]);G.startAbilities(b);assert.equal(G.speed(b,u(b,'heir')),1);assert.equal(b.run.roster.length,2)});
test('Crimson Hound has no opening or timed summon',()=>{let b=fixture([['hound',4]]);G.startAbilities(b);assert.equal(b.units.filter(v=>G.token(v)).length,0);G.extras(b,b.units[0],12);assert.equal(b.units.filter(v=>G.token(v)).length,0);assert.equal(b.run.roster.length,1)});
test('Conduit charges from distant attacks and grants nonstacking team haste',()=>{let b=fixture([['conduit',0],['cannon',8]]);enemy(b);for(let i=0;i<16;i++)G.attack(b,u(b,'cannon'));assert.equal(u(b,'cannon').hasteUntil,4);assert.equal(G.speed(b,u(b,'cannon')),1.15);G.tick(b,u(b,'conduit'),16);assert.equal(G.speed(b,u(b,'cannon')),1.15)});
test('Archmage chain hits five and feeds team growth and haste gauges',()=>{let b=fixture([['mage',1],['jade',8],['conduit',6]]),es=Array.from({length:6},(_,i)=>enemy(b,i));G.tick(b,u(b,'mage'),8);assert.equal(es[0].hp,10000);assert(es.slice(1).every(e=>e.hp<10000));assert.equal(u(b,'jade').threshold.current,2);assert.equal(u(b,'conduit').threshold.current,2)});
test('Autocannon shreds any target and distant Smelter grows it on burnout',()=>{let b=fixture([['cannon',0],['smelter',8]]),e=enemy(b,7,100000);for(let i=0;i<30;i++)G.attack(b,u(b,'cannon'));assert.equal(e.shredUntil,2);assert.equal(u(b,'cannon').permanentAtkBonus,1);assert.equal(u(b,'cannon').stateRemaining,5)});
test('Sensor grants team crit stats and Railgun volley ignores geometry',()=>{let b=fixture([['railgun',0],['sensor',8]]),es=Array.from({length:6},(_,i)=>enemy(b,i+3));assert.equal(G.sensor(b,u(b,'railgun')),1);assert.equal(G.crit(b,u(b,'railgun')),.2);G.attack(b,u(b,'railgun'));assert.equal(es[0].hp,10000);assert(es.slice(1).every(e=>e.hp<10000));assert.equal(es[5].p,7)});
test('Mantis boosts distant allies while overclocked and then shuts down',()=>{let b=fixture([['mantis',0],['jade',8]]);enemy(b,2,100000);advance(b,10.1);assert(u(b,'mantis').overclock);assert.equal(G.speed(b,u(b,'jade')),1.15);advance(b,5.1);assert.equal(u(b,'mantis').state,'overheat')});
test('Smelter and Vent cooling work teamwide and duplicate supports do not stack',()=>{let b=fixture([['cannon',0],['smelter',8],['smelter',6],['vent',7],['vent',5]]);assert.equal(G.downtime(b,u(b,'cannon'),6,'burnout'),2.5);assert.equal(G.downtime(b,u(b,'cannon'),5,'dormant'),4);G.flip(b,u(b,'cannon'),'burnout',6);assert.equal(u(b,'cannon').permanentAtkBonus,1)});
test('Vent freezes two leading enemies from any slot',()=>{let b=fixture([['vent',4]]),a=enemy(b,2),c=enemy(b,5),d=enemy(b,8);G.step(b,.05);assert.equal(a.frozenUntil,0);assert.equal(c.frozenUntil,1.05);assert.equal(d.frozenUntil,1.05)});
test('Totem enables distant armor penetration and unlimited attributable Bleed',()=>{let b=fixture([['totem',0],['cannon',8]]),e=enemy(b,2,10000,{defense:.8});for(let i=0;i<12;i++)G.attack(b,u(b,'cannon'));assert.equal(e.bleeds.length,12);assert.equal(e.bleeds[0].dps,2);assert.equal(e.bleeds[0].owner,u(b,'cannon').uid);assert(e.hp<10000)});
test('Executioner targets elites anywhere without self-generating permanent ATK',()=>{let b=fixture([['executioner',4]]),lead=enemy(b,10),elite=enemy(b,2,100,{hp:20,elite:true});G.attack(b,u(b,'executioner'));assert(lead.hp<10000);assert.equal(elite.hp,0);for(let i=0;i<20;i++)G.damage(b,enemy(b,1,1),2,u(b,'executioner'));assert.equal(u(b,'executioner').permanentAtkBonus,0)});
test('Eye warps two runners and adds vulnerability from any slot',()=>{let b=fixture([['eye',0]]),a=enemy(b,12),z=enemy(b,10);G.tick(b,u(b,'eye'),12);assert.equal(a.p,8);assert.equal(z.p,6);assert.equal(a.vulnerability,.15);assert.equal(a.vulnerableUntil,4)});
test('Shoggoth retains neighbor mimic but applies slow from every slot',()=>{let b=fixture([['mass',0],['railgun',1]]);G.startAbilities(b);assert.equal(G.rawAtk(u(b,'mass')),35);let e=enemy(b,8);G.attack(b,u(b,'mass'));assert(e.slows.some(v=>v.power===.2));b=fixture([['mass',0],['railgun',8]]);G.startAbilities(b);assert.equal(G.rawAtk(u(b,'mass')),15)});
test('breakthrough attribution follows a distant ally and survives the reward phase',()=>{let b=fixture([['jade',0],['cannon',8]]);b.feedback=[];enemy(b);for(let i=0;i<36;i++)G.attack(b,u(b,'cannon'));let event=b.feedback.find(e=>e.kind==='breakthrough');assert.equal(event.fromUid,u(b,'cannon').uid);assert(event.text.includes('+3'));G.finish(b,true);assert.equal(b.run.phase,'draft');assert.equal(b.run.roster[0].permanentAtkBonus,3)});
test('team-only builds produce identical outcomes after arbitrary slot permutation',()=>{let ids=['jade','cannon','smelter','bell','mage','sensor','railgun','mantis','totem'];let a=fixture(ids.map((id,i)=>[id,i])),b=fixture(ids.map((id,i)=>[id,8-i]));a.run.seed=b.run.seed=123;a.units.forEach(v=>v.currentCooldown=.3);b.units.forEach(v=>v.currentCooldown=.3);enemy(a,1,1000000,{speed:.01});enemy(b,1,1000000,{speed:.01});advance(a,60);advance(b,60);assert.equal(a.enemies[0].hp,b.enemies[0].hp);assert.deepEqual(a.run.roster,b.run.roster);assert.equal(a.metrics.growth,b.metrics.growth)});
test('most cards ignore placement and no card requires a fixed slot',()=>{assert(CARDS.filter(c=>c.fav==='neighbor').length<CARDS.length/2);assert(CARDS.every(c=>['team','neighbor','center'].includes(c.fav)))});

test('Jade and its evolution continue growing beyond the old limit',()=>{let b=fixture([['jade',0]]);for(let i=0;i<30;i++)G.tick(b,b.units[0],36);assert.equal(b.units[0].permanentAtkBonus,90)});
test('Mage casting deals spell damage without self-growing',()=>{let b=fixture([['mage',0]]),e=enemy(b,1,1000000);for(let i=0;i<20;i++)G.tick(b,b.units[0],8);assert.equal(b.units[0].permanentAtkBonus,0);assert(e.hp<1000000-20*95)});
test('Railgun critical hits do not generate permanent ATK',()=>{let b=fixture([['railgun',4]]);b.units[0].critGift=true;let e=enemy(b,1,1000000);for(let i=0;i<30;i++)G.hit(b,b.units[0],e,60);assert.equal(b.units[0].permanentAtkBonus,0)});
test('devour skips a grown non-Fodder attacker',()=>{let b=fixture([['heir',0],['jade',1]]);b.units[1].permanentAtkBonus=20;b.run.roster[1].permanentAtkBonus=20;G.startAbilities(b);assert.equal(b.units[0].permanentAtkBonus,0);assert.equal(b.run.roster.length,2)});
test('Heir gains ATK from meals only even after hundreds of attacks and reload',()=>{let b=fixture([['heir',0],['hound',1]]);G.devour(b,b.units[0]);enemy(b,1,1e8);for(let i=0;i<300;i++)G.attack(b,b.units[0]);assert.equal(b.units[0].permanentAtkBonus,3);G.finish(b,true);b.run.phase='ready';const z=G.deploy(JSON.parse(JSON.stringify(b.run)));assert.equal(z.units[0].permanentAtkBonus,3);assert.equal(z.units[0].threshold.max,0);});
test('rarity definitions and Bloodline tier ladder are correct',()=>{const {RARITIES,FORMS}=require('./dist/data.js');assert(['Normal','Rare','Epic','Legendary','Mythic'].every(t=>RARITIES.some(c=>c.id===t)));assert(['Normal','Rare','Epic','Legendary'].every(t=>CARDS.some(c=>c.rarity===t)));assert.equal(CARD.cub.rarity,'Normal');assert(FORMS.filter(c=>c.lineageTier).every(c=>c.rarity==={1:'Rare',2:'Epic',3:'Legendary',4:'Mythic'}[c.lineageTier]));assert(FORMS.filter(c=>c.tags?.includes('apex')).every(c=>c.rarity==='Mythic'));assert(!CARDS.some(c=>c.id==='familiar'));assert(CARD.familiar.retired)});
test('rarity unlocks and elite odds apply to every offer and reroll',()=>{let r=G.newRun('shen',{},71);for(let depth=-1;depth<15;depth++){r.depth=depth;r.node={type:'battle'};for(let j=0;j<30;j++){let offers=G.offers(r,depth===-1);assert.equal(offers.length,3);assert.equal(new Set(offers).size,3);if(depth<3)assert(offers.every(id=>G.tier(id)<2));if(depth<8)assert(offers.every(id=>G.tier(id)<3));}}r.depth=8;let regular=G.rewardWeights(r);r.node.type='elite';assert(G.rewardWeights(r)[3]>regular[3]);assert.equal(G.rewardWeights(r)[4],0);r.phase='draft';r.draftReason='reward';r.coins=10;r.offers=G.offers(r);assert(G.rerollDraft(r));assert.equal(r.coins,0);assert.equal(r.offers.length,3)});
test('nine unique genre leaders all expose a benefit and drawback',()=>{let ls=require('./dist/data.js').LEADERS;assert.equal(ls.length,9);assert.equal(new Set(ls.map(l=>l.genre)).size,9);assert(ls.every(l=>l.benefit&&l.drawback&&l.mods))});
test('Cultivation and Arcane leader modifiers work across genres',()=>{let b=fixture([['jade',0],['railgun',8]],'shen');assert.equal(G.atk(b,b.units[1]),31.5);G.tick(b,b.units[0],36);assert.equal(b.units[0].permanentAtkBonus,3.75);b=fixture([['jade',0],['conduit',8]],'lyra');G.tick(b,b.units[1],4);assert.equal(b.units[1].threshold.current,5);assert.equal(G.atk(b,b.units[0]),14*.85)});
test('Haunted duration and Cyberpunk speed tradeoffs apply teamwide',()=>{let b=fixture([['conduit',0],['cannon',8]],'yara');G.tick(b,b.units[0],16);assert.equal(b.units[1].hasteUntil,5.6);assert.equal(G.speed(b,b.units[1]),1.15*.9);b=fixture([['jade',0],['railgun',8]],'nyx');assert.equal(G.speed(b,b.units[1]),1.25);assert.equal(G.atk(b,b.units[0]),14*.85)});
test('retired Scarlet Familiar is not eligible prey for Cub, Blood Heir, or Progenitor',()=>{let b=fixture([['cub',4],['heir',1],['progenitor',7],['familiar',0]]);for(const eater of b.units.slice(0,3))assert.equal(G.preyEligible(eater,b.units[3]),false)});
test('Bloodline health and SciFi critical tradeoffs are universal',()=>{let b=fixture([['cannon',0]],'vesper');assert.equal(b.run.maxHealth,80);assert(Math.abs(G.crit(b,b.units[0])-.3)<1e-8);b=fixture([['jade',0]],'orion');assert.equal(G.crit(b,b.units[0]),.05);b.units[0].critGift=true;let e=enemy(b);G.hit(b,b.units[0],e,10);assert.equal(e.hp,9977)});
test('Post-apocalypse damage and Dark Fantasy targeting tradeoffs work',()=>{let b=fixture([['jade',0]],'rook');assert.equal(G.atk(b,b.units[0]),17.5);assert.equal(G.speed(b,b.units[0]),.85);b=fixture([['cannon',0]],'morrow');b.units[0].critGift=true;let boss=enemy(b,3,1000,{boss:true}),normal=enemy(b,2,1000);G.hit(b,b.units[0],boss,100);G.hit(b,b.units[0],normal,100);assert.equal(boss.hp,740);assert.equal(normal.hp,820)});
test('Cosmic Horror strengthens temporary haste and increases leak damage',()=>{let b=fixture([['conduit',0],['jade',8]],'naal');G.tick(b,b.units[0],16);assert.equal(G.speed(b,b.units[1]),1.265);b.units.forEach(u=>u.attackInterval=0);enemy(b,15.999,10,{leak:2});G.step(b,.1);assert.equal(b.run.health,97)});
test('non-Fodder Epic and Legendary attackers cannot be eaten',()=>{for(const id of ['eye','mage']){let b=fixture([['heir',0],[id,1]]);assert.equal(G.devour(b,b.units[0]),false);assert.equal(b.run.roster.length,2)}});
test('Herb offering gives its stated fixed sacrifice reward and frees its slot',()=>{let b=fixture([['herb',0],['jade',8]]);b.units[0].permanentAtkBonus=4;b.run.roster[0].permanentAtkBonus=4;assert(G.herbOffering(b,b.units[0]));assert.equal(b.run.roster.length,1);assert.equal(b.units.filter(u=>!u.removed).length,1);assert.equal(b.units[1].permanentAtkBonus,10);assert.equal(G.speed(b,b.units[1]),1.15);G.finish(b,true);b.run=JSON.parse(JSON.stringify(b.run));b.run.phase='ready';let next=G.deploy(b.run);assert(!next.units.some(u=>u.id==='herb'));assert.equal(next.units[0].offeringSpeed,0);assert(!('attachments' in b.run))});
test('Herb waits if there is no original attacking beneficiary',()=>{let b=fixture([['herb',0],['vent',8]]);assert.equal(G.herbOffering(b,b.units[0]),false);assert.equal(b.run.roster.length,2)});
test('Rare Mantis grows once per complete cycle while Epic Eye does not self-grow',()=>{let b=fixture([['mantis',0],['eye',8]]);enemy(b,1,1e7,{speed:0});advance(b,15.2);assert.equal(b.units[0].permanentAtkBonus,1);G.tick(b,b.units[1],12);G.damage(b,enemy(b,1,1),2,b.units[1]);assert.equal(b.units[1].permanentAtkBonus,0)});
test('Legendary Archmage does not generate growth from ally shutdown counters',()=>{let b=fixture([['mage',0],['cannon',8]]);G.tick(b,b.units[1],30);assert.equal(b.units[0].permanentAtkBonus,0)});
test('original and token meals pay identical rewards even with different stats',()=>{for(const id of ['heir','progenitor','herald']){const prey=id==='herald'?'mass':'hound';let a=fixture([[id,4],[prey,1]]),b=fixture([[id,4],['medium',8]]);a.units[1].permanentAtkBonus=500;let t=G.spawnToken(b,b.units[1],'echo',false,{origin:prey,tokenAtk:999});Object.assign(t,G.xy(1),{slot:1});assert(G.devour(a,a.units[0]));assert(G.devour(b,b.units[0]));assert.equal(a.units[0].permanentAtkBonus,b.units[0].permanentAtkBonus);assert.equal(a.run.roster.length,1);assert.equal(b.run.roster.length,2);assert.equal(b.metrics.consumed[0].permanent,false)}});
test('predators prioritize an adjacent eligible token over lower-ATK original Fodder',()=>{let b=fixture([['heir',4],['hound',1],['medium',8]]);const t=G.spawnToken(b,b.units[2],'echo',false,{origin:'hound',tokenAtk:100});Object.assign(t,G.xy(3),{slot:3});G.devour(b,b.units[0]);assert(t.removed);assert(!b.units[1].removed);assert.equal(b.run.roster.length,3)});
test('Herald rejects generic tokens and accepts only its specified ancestry',()=>{let b=fixture([['herald',4],['familiar',8]]);let t=G.spawnToken(b,b.units[1],'imp');Object.assign(t,G.xy(1),{slot:1});assert(!G.devour(b,b.units[0]));t.origin='larva';assert(G.devour(b,b.units[0]));assert.equal(b.units[0].permanentAtkBonus,10);assert.equal(b.units[0].madnessAt,4)});
test('eaten Lotus root never returns while its surviving token is temporary',()=>{let b=fixture([['alchemist',4],['lotus',1]]);let t=G.spawnToken(b,b.units[1],'petal',true);assert(t);assert(!G.neighbors(b,b.units[0]).includes(t));assert(G.devour(b,b.units[0]));assert(b.units[1].removed);assert(!t.removed);assert(!G.summon(b,b.units[1]));G.finish(b,true);b.run.phase='ready';const next=G.deploy(JSON.parse(JSON.stringify(b.run)));assert(!next.units.some(v=>v.id==='lotus'||v.id==='petal'));});
test('a parent and its offspring can spawn repeatedly until slots fill',()=>{let b=fixture([['familiar',4]]),p=b.units[0];const t=G.summon(b,p);assert(t);assert(G.summon(b,p));assert(G.spawnToken(b,t,'imp',false));while(G.spawnToken(b,p,'imp',false)){}assert.equal(b.units.filter(v=>!v.removed).length,9);assert.equal(G.spawnToken(b,p,'imp'),null);assert.equal(b.run.roster.length,1);});
test('full grid blocks summons and preserves all nine original slots',()=>{let b=fixture(Array.from({length:9},(_,i)=>[i===4?'familiar':'jade',i]));G.startAbilities(b);assert.equal(b.units.length,9);assert.equal(b.run.roster.length,9);});
test('opening abilities resolve once without granting Hound a free phantom',()=>{let b=fixture([['heir',0],['hound',4]]);G.startAbilities(b);assert.equal(b.units.filter(v=>G.token(v)).length,0);assert.equal(b.run.roster.length,2);G.startAbilities(b);assert.equal(b.metrics.devours,0)});
test('periodic feeding uses exact species and preserves unrelated allies',()=>{let b=fixture([['heir',4],['hound',1],['hound',3],['mage',5]]);G.devour(b,b.units[0]);b.units.forEach(v=>{v.attackInterval=0;v.summonAt=999;v.breedAt=999});enemy(b,1,1e7,{speed:0});advance(b,6.1);assert.equal(b.metrics.devours,2);assert(!b.units[3].removed);assert.equal(b.units[0].permanentAtkBonus,6);});
test('Lotus refinement resets maturity, preserves root, and selects lowest-growth attacker',()=>{let b=fixture([['lotus',0],['jade',8],['railgun',6]]);b.units[1].permanentAtkBonus=10;assert(G.refine(b,b.units[0]));assert.equal(b.units[2].permanentAtkBonus,6);assert.equal(b.units[1].threshold.current,3);assert.equal(b.units[0].threshold.current,0);assert.equal(b.run.roster.length,3);assert(!b.units[0].removed)});
test('Lotus refines automatically after eighteen seconds without needing to attack',()=>{let b=fixture([['lotus',0],['railgun',8]]);enemy(b,1,1e8,{speed:0});advance(b,18.1);assert(b.units[1].permanentAtkBonus>=6);assert(!b.units[0].removed);assert(b.units[0].threshold.current<1);});
test('Herb sacrifices at eighteen seconds and its haste expires next battle',()=>{let b=fixture([['herb',0],['jade',8]]);enemy(b,1,1e8,{speed:0});advance(b,17.9);assert(!b.units[0].removed);advance(b,.3);assert(b.units[0].removed);assert.equal(b.units[1].offeringSpeed,.15);G.finish(b,true);b.run.phase='ready';assert.equal(G.deploy(b.run).units[0].offeringSpeed,0)});
test('three meals evolve Heir in place and preserve run growth through reload',()=>{let b=fixture([['heir',4],['hound',1],['hound',3],['hound',5]]),h=b.units[0],uid=h.uid;for(let i=0;i<3;i++)assert(G.devour(b,h));assert.equal(h.id,'progenitor');assert.equal(h.uid,uid);assert.equal(h.slot,4);assert.equal(h.permanentAtkBonus,9);assert.equal(b.run.roster[0].id,'progenitor');G.finish(b,true);const r=JSON.parse(JSON.stringify(b.run));r.phase='ready';let next=G.deploy(r);assert.equal(next.units[0].id,'progenitor');assert.equal(next.units[0].permanentAtkBonus,9);assert.equal(r.roster.length,1);});
test('Jade evolution counts its own breakthroughs, not externally granted attack',()=>{let b=fixture([['jade',4]]),j=b.units[0];G.growth(b,j,100);assert.equal(j.id,'jade');for(let i=0;i<6;i++)G.tick(b,j,36);assert.equal(j.id,'immortal');assert.equal(j.permanentAtkBonus,118);assert.equal(b.run.roster[0].qiGrowth,18);let es=[enemy(b,1),enemy(b,2),enemy(b,3),enemy(b,4)];G.attack(b,j);assert.equal(es.filter(e=>e.hp<10000).length,3)});
test('Spirit evolves only after five completed Dormant returns',()=>{let b=fixture([['spirit',4]]),v=b.units[0];for(let i=0;i<4;i++){G.flip(b,v,'dormant',5);G.flip(b,v,'active');}assert.equal(v.id,'spirit');G.flip(b,v,'dormant',5);assert.equal(v.id,'spirit');G.flip(b,v,'active');assert.equal(v.id,'wraith');assert.equal(b.run.roster[0].returns,5)});
test('Wraith aura slows all enemies but does not generate endless Eye charge',()=>{let b=fixture([['wraith',0],['eye',8]]);b.units.forEach(v=>v.attackInterval=0);let e=enemy(b,1,1e6,{speed:1});advance(b,1);assert(Math.abs(e.p-1.7)<.02);assert.equal(b.units[1].threshold.current,0)});
test('Monk counts original losses across the team and excludes tokens',()=>{let b=fixture([['monk',8],['heir',4],['herb',1],['mass',3],['leech',5],['medium',6]]);let t=G.spawnToken(b,b.units[5],'echo');G.consume(b,b.units[1],t,'Devour',12);G.flushEvents(b);assert.equal(b.units[0].witnesses||0,0);for(let i of [2,3,4]){G.consume(b,b.units[1],b.units[i],'Devour',12);G.flushEvents(b);}assert.equal(b.units[0].id,'asura');assert.equal(b.run.roster.find(v=>v.uid===b.units[0].uid).id,'asura')});
test('Asura guarantees critical hits against shred and applies its own Bleed',()=>{let b=fixture([['asura',4]]),e=enemy(b,1,10000,{shredUntil:10});G.attack(b,b.units[0]);assert.equal(e.hp,10000-48);assert.equal(e.bleeds[0].dps,6);});
test('Cauldron cannot recursively brew itself and respects cooldown without a battle cap',()=>{let b=fixture([['cauldron',0],['jade',8]]);b.run.health=50;for(let i=0;i<20;i++){b.time=i*8;G.event(b,'breakthrough',{unit:b.units[1]});G.flushEvents(b);}assert.equal(b.units[0].elixirs,20);assert.equal(b.run.health,70);assert.equal(b.units[1].permanentAtkBonus,20);assert.equal(b.events.length,0);});
test('temporary token growth is excluded from permanent run and recap totals',()=>{let b=fixture([['hound',4]]),t=G.spawnToken(b,b.units[0],'houndToken',true,{origin:'hound',tokenAtk:16});const before=G.rawAtk(t);G.growth(b,t,2);assert.equal(G.rawAtk(t),before+2);assert.equal(b.run.stats.growth,0);assert.equal(b.metrics.growth,0);assert.equal(G.record(b,t).temporaryGrowth,2)});
test('Medium echo does not resurrect deleted original or copy summoning powers',()=>{let b=fixture([['herald',0],['mass',1],['medium',8]]);G.devour(b,b.units[0]);const m=b.units[2];assert(m.pendingEcho);G.extras(b,m,.1);const t=b.units.find(v=>v.id==='echo');assert(t);assert.equal(t.origin,'mass');assert.equal(G.rawAtk(t),15);assert.equal(b.run.roster.length,2);assert(!b.run.roster.some(v=>v.id==='mass'));assert.equal(G.summon(b,t),undefined);G.event(b,'shutdown',{unit:b.units[0],state:'dormant'});G.flushEvents(b);assert(!m.pendingEcho)});
test('Medium holds a single echo until an empty slot is available',()=>{let b=fixture([['medium',0],['spirit',1],...Array.from({length:7},(_,i)=>['jade',i+2])]);G.flip(b,b.units[1],'dormant',5);G.flushEvents(b);G.extras(b,b.units[0],.1);assert(b.units[0].pendingEcho);b.units[8].removed=true;G.extras(b,b.units[0],.1);assert(!b.units[0].pendingEcho);assert.equal(b.units.filter(v=>!v.removed).length,9);});
test('Burn stacks are unlimited, attributed, expire, and trigger stronger Vent freeze',()=>{let b=fixture([['bellows',0],['vent',8]]),e=enemy(b,2,1e6);for(let i=0;i<20;i++)G.dot(b,e,'burn',8,4,b.units[0]);assert.equal(e.burns.length,20);assert(e.burns.every(d=>d.owner===b.units[0].uid));b.units[0].attackInterval=0;G.step(b,.05);assert.equal(e.frozenUntil,2.05);assert(G.record(b,b.units[0]).dot>0);advance(b,4.1);assert.equal(e.burns.length,0);});
test('Burnout detonation credits Burn owners and cannot recursively repeat',()=>{let b=fixture([['bellows',0],['plasma',1],['cannon',8]]),e=enemy(b,2,10000);G.dot(b,e,'burn',12,4,b.units[1]);G.flip(b,b.units[2],'burnout',6);G.flushEvents(b);assert.equal(e.hp,9988);assert.equal(G.record(b,b.units[1]).dot,12);G.flip(b,b.units[2],'burnout',6);G.flushEvents(b);assert.equal(e.hp,9988)});
test('Smelter forging keeps growing through cycles and burning kills',()=>{let b=fixture([['smelter',0],['cannon',8]]);for(let i=0;i<20;i++)G.flip(b,b.units[1],'burnout',6);assert.equal(b.units[1].permanentAtkBonus,20);for(let i=0;i<10;i++){G.event(b,'kill',{burning:true});G.flushEvents(b);}assert.equal(b.units[1].permanentAtkBonus,22)});
test('Lantern converts state changes and deaths into a bounded area shockwave',()=>{let b=fixture([['lantern',0],['spirit',8]]),e=enemy(b,2,10000);for(let i=0;i<10;i++)G.event(b,'shutdown',{unit:b.units[1],state:'dormant'});G.flushEvents(b);assert(e.hp<=9955);assert.equal(b.units[0].nextTrigger,2);assert.equal(b.units[0].threshold.current,0)});
test('Crystal battery charges ability gauges but never forces shutdown or becomes generic prey',()=>{let b=fixture([['heir',4],['crystal',1],['weaver',8],['cannon',6]]);assert(!G.devour(b,b.units[0]));b.time=4;G.extras(b,b.units[1],.1);assert.equal(b.units[2].threshold.current,2);assert.equal(b.units[3].threshold.current,0);assert.equal(b.units[3].state,'active');});
test('Altar growth applies only to original orthogonal neighbors without a cap',()=>{let b=fixture([['altar',4],['jade',1],['jade',0]]);for(let i=0;i<20;i++){G.event(b,'kill',{bleeding:true});G.flushEvents(b);}assert.equal(b.units[1].permanentAtkBonus,20);assert.equal(b.units[2].permanentAtkBonus,0)});
test('Singularity counts direct critical hits, respects cooldown, and cannot charge itself',()=>{let b=fixture([['core',0],['cannon',8]]),e=enemy(b,10,1e7);b.units[1].critGift=true;for(let i=0;i<8;i++)G.hit(b,b.units[1],e,1);assert.equal(e.p,7.5);assert.equal(b.units[0].threshold.current,0);for(let i=0;i<8;i++)G.hit(b,b.units[1],e,1);assert.equal(e.p,7.5);assert.equal(b.units[0].threshold.current,8);b.time=6;G.tick(b,b.units[0],0);assert.equal(e.p,5);});
test('Reaper consumes Bleed stacks for burst without self-growing',()=>{let b=fixture([['reaper',4]]),e=enemy(b,2,1000,{hp:100});for(let i=0;i<4;i++)G.dot(b,e,'bleed',5,4,b.units[0]);G.attack(b,b.units[0]);assert.equal(e.hp,0);assert.equal(e.bleeds.length,0);assert.equal(b.units[0].permanentAtkBonus,0)});
test('Plasma shuts down after twelve attacks and applies owned Burn',()=>{let b=fixture([['plasma',4]]),e=enemy(b,2,1e7);for(let i=0;i<12;i++)G.attack(b,b.units[0]);assert.equal(b.units[0].state,'overheat');assert(e.burns.length);assert.equal(e.burns[0].owner,b.units[0].uid)});
test('Behemoth quake bypasses armor and has a defined burnout cycle',()=>{let b=fixture([['behemoth',4]]),e=enemy(b,2,10000,{defense:1});G.tick(b,b.units[0],10);assert.equal(e.hp,9400);assert.equal(b.units[0].state,'burnout');assert.equal(b.units[0].permanentAtkBonus,0)});
test('Netrunner selects fastest enemy and gives only orthogonal nonstacking haste',()=>{let b=fixture([['netrunner',4],['jade',1],['jade',0]]),a=enemy(b,1,10000,{speed:2}),z=enemy(b,10,10000,{speed:.3});b.time=5;G.extras(b,b.units[0],.1);assert.equal(a.slows[0].power,.5);assert.equal(z.slows.length,0);assert.equal(G.speed(b,b.units[1]),1.15);assert.equal(G.speed(b,b.units[2]),1)});
test('Leech benefits from both Burn and Bleed without inheriting eater rewards',()=>{for(const type of ['burn','bleed']){let b=fixture([['leech',4]]),e=enemy(b);G.dot(b,e,type,1,4,b.units[0]);G.attack(b,b.units[0]);assert([9967.5,9935,9980,9960].includes(e.hp));}});
test('new forms and tokens never appear in ordinary drafts or rerolls',()=>{let r=G.newRun('shen',{},37);r.depth=14;r.node={type:'elite'};for(let i=0;i<300;i++){const ids=G.offers(r);assert(ids.every(id=>CARDS.some(c=>c.id===id)));assert.equal(new Set(ids).size,3);}});
test('all draftable cards and evolved forms can complete a combat without NaN or overlap',()=>{for(const c of [...CARDS,...require('./dist/data.js').FORMS]){let b=fixture([[c.id,4],['cannon',0],['lotus',8]]);G.startAbilities(b);enemy(b,1,1000000,{speed:.01});advance(b,90);assert(Number.isFinite(b.run.health),c.id);assert(b.units.every(v=>Number.isFinite(v.permanentAtkBonus)),c.id);const active=b.units.filter(v=>!v.removed);assert(active.length<=9,c.id);assert.equal(new Set(active.map(v=>v.slot)).size,active.length,c.id);}});

test('support echoes cannot create zero-damage attacks to charge team gauges',()=>{let b=fixture([['alchemist',4],['herb',1],['medium',8]]);G.devour(b,b.units[0]);G.extras(b,b.units[2],.1);let t=b.units.find(v=>v.id==='echo');assert(t);assert.equal(t.attackInterval,0)});
test('Vulnerable amplifies attributed Burn damage without changing stack duration',()=>{let b=fixture([['bellows',4]]),e=enemy(b,1,1000);b.units[0].attackInterval=0;G.dot(b,e,'burn',10,4,b.units[0]);G.status(b,e,'vulnerable',4,.2);G.step(b,.1);assert(Math.abs(e.hp-998.8)<1e-8);assert.equal(e.burns[0].until,4)});
test('breeding rolls once per second per unit, not once per matching neighbor',()=>{let b=fixture([['familiar',4],['familiar',1],['familiar',3]]),v=b.units[0];b.time=1;b.run.seed=42;G.breed(b,v);let seed=b.run.seed;G.breed(b,v);assert.equal(b.run.seed,seed);assert.equal(b.metrics.breedingChecks,1);b.time=2;G.breed(b,v);assert.equal(b.metrics.breedingChecks,2);});
test('breeding needs the same species and an empty orthogonal slot',()=>{let b=fixture([['familiar',4],['hound',1]]);b.time=1;let seed=b.run.seed;G.breed(b,b.units[0]);assert.equal(b.run.seed,seed);b=fixture([['familiar',4],['familiar',1],['jade',3],['jade',5],['jade',7]]);b.time=1;seed=b.run.seed;G.breed(b,b.units[0]);assert.equal(b.run.seed,seed);});
test('token breeding copies ATK at birth and neither inherits future original growth nor a growth engine',()=>{let b=fixture([['familiar',4]]),p=b.units[0];G.growth(b,p,30);let t=G.summon(b,p);assert.equal(G.rawAtk(t),40);assert.equal(t.attackInterval,1.1);G.growth(b,p,20);assert.equal(G.rawAtk(t),40);b.time=1;let spawned=false;for(let seed=10000;seed<20000&&!spawned;seed++){t.breedAt=1;b.run.seed=seed;let before=b.units.length;G.breed(b,t);spawned=b.units.length>before;}assert(spawned);const child=b.units.at(-1);assert.equal(G.rawAtk(child),40);assert.equal(G.species(child),'familiar');assert.equal(b.run.roster.length,1);});
test('token offspring inherit basic Bloodline Bleed',()=>{let b=fixture([['familiar',4]]),t=G.summon(b,b.units[0]),e=enemy(b);G.attack(b,t);assert.equal(e.bleeds[0].dps,3);assert.equal(e.bleeds[0].owner,t.uid);});
test('every predator rejects unrelated prey, including foreign tokens',()=>{const diets={heir:['familiar','hound'],herald:['mass','larva'],alchemist:['lotus','herb'],harvester:['lamb']};for(const [id,allowed]of Object.entries(diets))for(const c of CARDS){let b=fixture([[id,4],[c.id,1]]);assert.equal(G.preyEligible(b.units[0],b.units[1]),allowed.includes(c.id),id+' / '+c.id);const t=G.spawnToken(b,b.units[1],'echo',false,{origin:c.id});assert.equal(G.preyEligible(b.units[0],t),allowed.includes(c.id),'token '+id+' / '+c.id);}});
test('Broodkeeper globally recalls any of the five consumed Bloodline fodders as its species token',()=>{for(const prey of ['serpentFodder','hound','scuttler','flameToad','peachFodder']){let found=false;for(let seed=1;seed<1000&&!found;seed++){let b=fixture([['cub',0],[prey,1],['broodkeeper',8]]);b.run.seed=seed;assert(G.devour(b,b.units[0]));const t=b.units.find(v=>v.token);if(t){found=true;assert.equal(G.species(t),prey,prey);assert.equal(t.origin,prey);assert.equal(t.tokenAtk,CARD[prey].baseAtk,prey);assert(Math.abs(b.units[1].x-b.units[2].x)+Math.abs(b.units[1].y-b.units[2].y)>1,'Broodkeeper consumes prey without adjacency');assert(!b.run.roster.some(v=>v.uid===b.metrics.consumed[0].uid),'consumed original stays removed');}}assert(found,prey+' should trigger globally')}});
test('Tiger line abilities inherit through Slaughter War Tiger and Apex',()=>{for(const id of ['tigerCubT3','tigerCubApex']){let b=fixture([[id,4]]),u=b.units[0];assert.equal(G.crit(b,u),.25,id+' retains +15% crit');const e=enemy(b,3,10000);G.attack(b,u);assert(e.bleeds.some(d=>d.dps===3),id+' applies inherited Bleed');const marked=enemy(b,2,10000);G.dot(b,marked,'bleed',1,4,u);u.critGift=true;const before=marked.hp;G.hit(b,u,marked,100);assert.equal(before-marked.hp,300,id+' deals triple critical damage to bleeding targets')}});
test('Slaughter War Tiger prioritizes elites and retains its low-health execution',()=>{let b=fixture([['tigerCubT3',4]]),u=b.units[0],normal=enemy(b,10,10000),elite=enemy(b,2,10000,{elite:true});G.attack(b,u);assert.equal(normal.hp,10000);assert(elite.hp<10000);normal.hp=0;normal.gone=true;elite.hp=0;elite.gone=true;let low=enemy(b,3,10000,{hp:3900});const before=low.hp;G.attack(b,u);assert(before-low.hp>=95*3)});
test('Matriarch snapshots population into Bloodline Bleed duration only',()=>{let b=fixture([['familiar',0],['hound',8],['matriarch',4],['asura',6]]),e=enemy(b);G.dot(b,e,'bleed',3,4,b.units[1]);assert.equal(e.bleeds[0].until,5);G.dot(b,e,'bleed',3,4,b.units[3]);assert.equal(e.bleeds[1].until,4);b.units[1].removed=true;assert.equal(e.bleeds[0].until,5);G.dot(b,e,'bleed',3,4,b.units[0]);assert.equal(e.bleeds[2].until,4.5);});
test('Herb waits rather than offering to a foreign attacker',()=>{let b=fixture([['herb',0],['railgun',8]]);assert(!G.herbOffering(b,b.units[0]));assert(!b.units[0].removed);});
test('Alchemist consumes a Petal for growth and charge without deleting its root',()=>{let b=fixture([['alchemist',4],['lotus',0],['jade',8]]),t=G.spawnToken(b,b.units[1],'petal',true);assert.equal(t.slot,1);G.devour(b,b.units[0]);assert(t.removed);assert(!b.units[1].removed);assert.equal(b.units[0].permanentAtkBonus,3);assert.equal(b.units[2].threshold.current,3);});
test('Haunted sacrifice grants growth, Lantern Echoes, and stronger Soul Well missiles',()=>{let b=fixture([['harvester',4],['lamb',1],['lantern',8],['soulwell',6]]),e=enemy(b);G.devour(b,b.units[0]);assert.equal(b.units[0].permanentAtkBonus,6);assert.equal(b.units[2].threshold.current,3);assert(G.record(b,b.units[3]).ability>=182);assert(b.units[1].removed);assert(e.hp<10000);});
test('Soul Well reacts across genres without sharing predator diets',()=>{let b=fixture([['heir',4],['hound',1],['soulwell',8]]),e=enemy(b);G.devour(b,b.units[0]);assert.equal(G.record(b,b.units[2]).ability,81.5);assert(!G.preyEligible(b.units[0],b.units[2]));assert(e.hp<10000);});
test('Shepherd keeps summoning and tokens fill all free slots',()=>{let b=fixture([['shepherd',4]]),p=b.units[0];for(let i=0;i<12;i++){b.time=i*8;G.extras(b,p,.1);}assert.equal(b.units.filter(v=>!v.removed).length,9);assert.equal(b.run.roster.length,1);assert(b.units.slice(1).every(t=>G.rawAtk(t)===8));});
test('Medium can hold multiple active echoes over time without restoring originals',()=>{let b=fixture([['medium',0],['spirit',8]]);for(let i=0;i<3;i++){b.time=i*10;G.event(b,'shutdown',{unit:b.units[1],state:'dormant'});G.flushEvents(b);G.extras(b,b.units[0],.1);}assert.equal(b.units.filter(v=>v.token).length,3);assert.equal(b.run.roster.length,2);});
test('catalyst timing selects each awakening and permanently removes only the catalyst',()=>{for(const [time,path]of [[1,'might'],[4,'flow'],[8,'storm']]){let b=fixture([['jade',4],['catalyst',1]]);b.time=time;G.extras(b,b.units[0],.1);assert.equal(b.units[0].id,'immortal');assert.equal(b.units[0].upgradePath,path);assert.equal(b.run.roster.length,1);assert.equal(b.run.roster[0].upgradePath,path);if(path==='flow')assert.equal(b.run.roster[0].permanentSpeed,.2);}});
test('workshop is visible at crossings 4, 8, 12 and offers three actual choices',()=>{let r=G.newRun('shen',{},4);assert([3,7,11].every(row=>r.map[row][1].type==='workshop'));r.roster=[G.instance(r,'jade'),G.instance(r,'sensor')];assert.deepEqual(G.workshopOptions(r,1).map(o=>o.id),['might','flow','storm']);assert.deepEqual(G.workshopOptions(r,2).map(o=>o.id),['power','tempo','resonance']);});
test('workshop purchases validate phase, cost and choice, retaining growth and identity',()=>{let r=G.newRun('shen',{},4);r.roster=[G.instance(r,'jade')];r.roster[0].permanentAtkBonus=33;assert(!G.upgrade(r,1,'might'));r.phase='event';r.node={type:'workshop'};r.health=10;assert(!G.upgrade(r,1,'might'));r.health=50;assert(!G.upgrade(r,1,'invalid'));assert(G.upgrade(r,1,'flow'));assert.equal(r.health,40);assert.equal(r.phase,'draft');assert.equal(r.roster[0].id,'immortal');assert.equal(r.roster[0].permanentAtkBonus,33);assert.equal(r.roster[0].permanentSpeed,.2);assert(!G.upgrade(r,1,'power'));r=JSON.parse(JSON.stringify(r));r.phase='ready';r.depth=4;r.node={type:'battle'};const b=G.deploy(r);assert.equal(G.speed(b,b.units[0]),1.2);});
test('support workshop Resonance charges real ability gauges',()=>{let b=fixture([['sensor',0],['jade',8]]);b.units[0].resonanceLevel=2;b.time=6;G.extras(b,b.units[0],.1);assert.equal(b.units[1].threshold.current,2);});
test('Storm evolution path adds a real sixth-attack burst',()=>{let b=fixture([['immortal',4]]),v=b.units[0];v.upgradePath='storm';v.attackCount=5;let e=enemy(b);G.attack(b,v);assert(G.record(b,v).ability>=20);assert(e.hp<9980);});
test('Nanite unfinished critical growth progress survives battles',()=>{let b=fixture([['nanite',4]]),v=b.units[0],e=enemy(b,1,1e6);v.critGift=true;for(let i=0;i<5;i++)G.hit(b,v,e,1);G.finish(b,true);b.run.phase='ready';const z=G.deploy(JSON.parse(JSON.stringify(b.run))),n=z.units[0];n.critGift=true;G.hit(z,n,enemy(z),1);assert.equal(n.permanentAtkBonus,1);});
test('spell resonance is throttled and cannot recursively trigger itself',()=>{let b=fixture([['mage',0],['weaver',8],['jade',4]]);enemy(b,1,1e8);for(let i=0;i<20;i++)G.event(b,'gauge',{unit:b.units[2]});G.flushEvents(b);assert.equal(b.units[0].threshold.current,2);assert.equal(b.units[1].threshold.current,2);G.event(b,'gauge',{unit:b.units[0]});G.flushEvents(b);assert.equal(b.units[1].threshold.current,2);});
test('Behemoth receives charge from allied shutdowns but not its own',()=>{let b=fixture([['behemoth',0],['cannon',8]]);enemy(b);G.flip(b,b.units[1],'burnout',6);G.flushEvents(b);assert.equal(b.units[0].threshold.current,3);G.flip(b,b.units[0],'burnout',5);G.flushEvents(b);assert.equal(b.units[0].threshold.current,3);});
test('Railgun ignores armor while still crediting direct critical hits',()=>{let b=fixture([['railgun',0]]),e=enemy(b,1,10000,{defense:1});b.units[0].critGift=true;G.attack(b,b.units[0]);assert.equal(e.hp,9930);assert.equal(G.record(b,b.units[0]).direct,70);});
test('Herald stores actual allied displacement, not resisted or self-generated pulls',()=>{let b=fixture([['herald',0],['eye',8]]),e=enemy(b,10);G.warp(b,e,4,b.units[1]);G.flushEvents(b);assert.equal(b.units[0].madnessPower,120);e.enraged=true;e.boss=true;G.warp(b,e,4,b.units[1]);G.flushEvents(b);assert.equal(b.units[0].madnessPower,120);b.time=8;G.extras(b,b.units[0],.1);G.flushEvents(b);assert.equal(b.units[0].madnessPower,0);assert(G.record(b,b.units[0]).ability>=320);});
test('Reaper transfers unconsumed Bleed without refreshing expiry or ownership',()=>{let b=fixture([['reaper',0],['familiar',8]]),a=enemy(b,10,10),z=enemy(b,5);G.dot(b,a,'bleed',3,4,b.units[1]);b.time=2;G.damage(b,a,20,b.units[0]);G.flushEvents(b);assert.equal(z.bleeds.length,1);assert.equal(z.bleeds[0].until,4);assert.equal(z.bleeds[0].owner,b.units[1].uid);});


test('Cultivation Qi thresholds persist as earned Rare, Epic and Legendary forms',()=>{let b=fixture([['practitioner',4]]),v=u(b,'practitioner');for(const [qi,realm,id] of [[29,0,'practitioner'],[30,1,'cultivationFoundation'],[84,1,'cultivationFoundation'],[85,2,'cultivationGoldenCore'],[174,2,'cultivationGoldenCore'],[175,3,'cultivationNascentSoul']]){v.qi=qi;G.updatePractitionerRealm(b,v);assert.equal(v.realm,realm);assert.equal(v.id,id);assert.equal(b.run.roster.find(x=>x.uid===v.uid).id,id)}assert.equal(CARD.cultivationFoundation.rarity,'Rare');assert.equal(CARD.cultivationGoldenCore.rarity,'Epic');assert.equal(CARD.cultivationNascentSoul.rarity,'Legendary');let stale={...b.run.roster[0],id:'cultivationNascentSoul',qi:0,realm:3};let r=G.runtime(b,stale,4);G.updatePractitionerRealm(b,r);assert.equal(r.id,'practitioner');assert.equal(r.baseAtk,6);});
test('Flying Sword cannot ascend a Qi-Refining Practitioner before Nascent Soul',()=>{let b=fixture([['practitioner',4],['flyingSword',3],['lotusBlossom',1]]),v=u(b,'practitioner'),s=u(b,'flyingSword');v.realm=3;v.qi=0;G.extras(b,v,.1);assert.equal(v.id,'practitioner');assert.equal(v.realm,0);assert.equal(v.qi,15);assert(!s.removed);});
test('Nascent Soul earned form still awakens into its relic Apex',()=>{let b=fixture([['practitioner',4],['flyingSword',3]]),v=u(b,'practitioner'),s=u(b,'flyingSword');v.qi=174;G.updatePractitionerRealm(b,v);assert.equal(v.id,'cultivationGoldenCore');v.qi=175;G.updatePractitionerRealm(b,v);assert.equal(v.id,'cultivationNascentSoul');G.extras(b,v,.1);assert.equal(v.id,'swordImmortal');assert(s.removed);});
test('Sword Immortal consumes blossoms and converts every 30 post-ascension Qi to +2 permanent ATK',()=>{let b=fixture([['swordImmortal',4],['lotusBlossom',1],['lotusBlossom',3]]),v=u(b,'swordImmortal');v.qi=175;G.extras(b,v,.1);assert.equal(v.qi,190);assert.equal(v.swordQi,15);assert.equal(v.permanentAtkBonus,0);G.extras(b,v,.1);assert.equal(v.qi,205);assert.equal(v.swordQi,0);assert.equal(v.permanentAtkBonus,2);assert.equal(b.run.roster.find(x=>x.uid===v.uid).swordQi,0);});


test('Dragon abilities persist and combine through every tier',()=>{let b=fixture([['dragonCubT2',4]]),u=b.units[0],es=Array.from({length:4},(_,i)=>enemy(b,4-i,1e7));for(let i=0;i<4;i++)G.attack(b,u);assert(es.slice(0,3).every(e=>e.hp<1e7),'fourth hit reaches three leading runners');assert(es[0].hp<1e7-100,'fourth strike double damage stacks with earlier hits');b=fixture([['dragonCubApex',4]]);u=b.units[0];es=Array.from({length:7},(_,i)=>enemy(b,7-i,1e7));G.attack(b,u);assert(es.slice(0,6).every(e=>e.hp<1e7));b.time=8;G.extras(b,u,.01);assert(es.slice(0,6).some(e=>e.p===0));});
test('Xuanwu tiers inherit slow, Venom, pulse, speed punish, and leak prevention',()=>{let b=fixture([['xuanwuCubT2',4]]),u=b.units[0],a=enemy(b,3,1e6),z=enemy(b,2,1e6);u.attackCount=4;G.attack(b,u);assert(a.venoms.length&&z.hp<1e6-119);b=fixture([['xuanwuCubT3',4]]);u=b.units[0];a=enemy(b,1,1e6,{swift:true});G.attack(b,u);assert(a.frozenUntil>0);assert(a.venoms.length);b=fixture([['xuanwuCubApex',4]]);u=b.units[0];b.run.health=1;a=enemy(b,15.999,100);G.step(b,.1);assert.equal(b.run.health,1);assert.equal(b.metrics.leaks,0);assert.equal(a.gone,true);assert.equal(u.savedLeaks,1);});
test('Phoenix tiers inherit Burn, spread and vulnerability; Apex revives once',()=>{let b=fixture([['phoenixCubT2',4]]),u=b.units[0],a=enemy(b,1,1e6),z=enemy(b,2,1e6);G.attack(b,u);assert(a.burns.length&&z.burns.length);assert.equal(z.vulnerability,.15);b=fixture([['phoenixCubT3',4]]);u=b.units[0];a=enemy(b,1,1e6);a.burns=[{until:20,dps:5,owner:u.uid}];b.time=8;const before=a.hp;G.extras(b,u,.01);assert(a.hp<before-59);assert.equal(a.burns.length,0);b=fixture([['phoenixCubApex',4]]);u=b.units[0];b.run.health=1;a=enemy(b,15.999,100);G.step(b,.1);assert.equal(b.run.health,1);assert.equal(b.run.phoenixRevived,true);assert.notEqual(b.run.phase,'lost');});
test('Monkey tiers inherit extra crit, clones, cleave, and Apex true damage',()=>{let b=fixture([['monkeyCubT1',4]]),u=b.units[0];assert.equal(G.crit(b,u),.2);b=fixture([['monkeyCubT2',4]]);u=b.units[0];enemy(b,1,1e6);for(let i=0;i<6;i++)G.attack(b,u);const clone=b.units.find(v=>v.token);assert(clone);assert.equal(clone.id,'monkeyCubT2');assert.equal(clone.tokenAtk,G.rawAtk(u)*.5);b=fixture([['monkeyCubT3',4]]);u=b.units[0];let es=Array.from({length:4},(_,i)=>enemy(b,4-i,1e6));G.attack(b,u);assert(es.slice(0,3).every(e=>e.hp<1e6));assert.equal(es[3].hp,1e6);b=fixture([['monkeyCubApex',4]]);u=b.units[0];let e=enemy(b,1,1e6,{speedBoostUntil:5,auras:[{power:1}]});G.attack(b,u);assert(e.speedBoostUntil===0);assert.equal(e.auras.length,0);assert(e.hp<1e6-250);});

console.log(`${passed} mechanics tests passed.`);
if(!process.argv.includes('--mechanics-only')){
 const priority=['totem','bell','spirit','executioner','railgun','mage','cannon','jade','mantis','eye','heir','hound','conduit','mass','smelter','vent','herb','sensor'];
 let results=[];
 for(const leader of ['shen','yara','vesper','lyra'])for(let seed=1;seed<=3;seed++){
  let r=G.newRun(leader,{},seed),seconds=0,guard=0;
  while(!['lost','won'].includes(r.phase)&&guard++<90){
   if(r.phase==='draft'){let pick=process.argv.includes('--random-drafts')?r.offers[0]:[...r.offers].sort((a,b)=>priority.indexOf(a)-priority.indexOf(b))[0];G.draft(r,pick)}
   else if(r.phase==='map'){let opts=G.available(r),order=r.health<65?['rest','cache','event','battle','elite','boss']:['cache','battle','rest','event','elite','boss'];opts.sort((a,b)=>order.indexOf(a.type)-order.indexOf(b.type));G.chooseNode(r,opts[0].id)}
   else if(r.phase==='event'){if(r.node.type==='cache'){let relic=require('./dist/data.js').RELICS.find(v=>!r.relics.includes(v.id));if(relic)G.addRelic(r,relic.id)}else r.health=Math.min(r.maxHealth,r.health+(r.node.type==='rest'?12:3));G.reward(r)}
   else if(r.phase==='ready'){let b=G.deploy(r);advance(b,900);assert(b.done,'Combat stalled');seconds+=b.time;}
  }
  results.push({leader,seed,result:r.phase,depth:r.depth+1,hp:r.health,seconds:Math.round(seconds),growth:Math.round(r.stats.growth)});
 }
 console.table(results);
}

